PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(80) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id"), "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id"), UNIQUE ("group_id", "permission_id"));
CREATE TABLE IF NOT EXISTS "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id"), "group_id" integer NOT NULL REFERENCES "auth_group" ("id"), UNIQUE ("user_id", "group_id"));
CREATE TABLE IF NOT EXISTS "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id"), "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id"), UNIQUE ("user_id", "permission_id"));
CREATE TABLE IF NOT EXISTS "social_auth_nonce" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "server_url" varchar(255) NOT NULL, "timestamp" integer NOT NULL, "salt" varchar(65) NOT NULL);
CREATE TABLE IF NOT EXISTS "accounts_verifiedemail" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "social_id" integer NOT NULL REFERENCES "social_auth_usersocialauth" ("id"), "email" varchar(254) NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "accounts_profile_languages" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language_id" integer NOT NULL REFERENCES "lang_language" ("id"), "profile_id" integer NOT NULL REFERENCES "accounts_profile" ("id"), UNIQUE ("profile_id", "language_id"));
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL, UNIQUE ("app_label", "model"));
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id"), "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL, UNIQUE ("content_type_id", "codename"));
CREATE TABLE IF NOT EXISTS "trans_dictionary" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "source" varchar(190) NOT NULL, "language_id" integer NOT NULL REFERENCES "lang_language" ("id"), "project_id" integer NOT NULL REFERENCES "trans_project" ("id"), "target" varchar(190) NOT NULL);
CREATE TABLE IF NOT EXISTS "django_site" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(50) NOT NULL, "domain" varchar(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "accounts_profile_secondary_languages" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "profile_id" integer NOT NULL REFERENCES "accounts_profile" ("id"), "language_id" integer NOT NULL REFERENCES "lang_language" ("id"));
CREATE TABLE IF NOT EXISTS "social_auth_association" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "server_url" varchar(255) NOT NULL, "handle" varchar(255) NOT NULL, "secret" varchar(255) NOT NULL, "issued" integer NOT NULL, "lifetime" integer NOT NULL, "assoc_type" varchar(64) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "first_name" varchar(30) NOT NULL, "last_name" varchar(30) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "username" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "screenshots_screenshot_sources" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "screenshot_id" integer NOT NULL REFERENCES "screenshots_screenshot" ("id"), "source_id" integer NOT NULL REFERENCES "trans_source" ("id"));
CREATE TABLE IF NOT EXISTS "trans_autocomponentlist" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "component_match" varchar(200) NOT NULL, "componentlist_id" integer NOT NULL REFERENCES "trans_componentlist" ("id"), "project_match" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "social_auth_code" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "email" varchar(254) NOT NULL, "code" varchar(32) NOT NULL, "verified" bool NOT NULL, "timestamp" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "social_auth_partial" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "token" varchar(32) NOT NULL, "next_step" smallint unsigned NOT NULL, "backend" varchar(32) NOT NULL, "data" text NOT NULL, "timestamp" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "lang_language" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(50) NOT NULL UNIQUE, "name" varchar(100) NOT NULL, "direction" varchar(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "checks_check" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "check" varchar(50) NOT NULL, "ignore" bool NOT NULL, "language_id" integer NULL REFERENCES "lang_language" ("id"), "project_id" integer NOT NULL REFERENCES "trans_project" ("id"), "content_hash" bigint NOT NULL);
CREATE TABLE IF NOT EXISTS "trans_unit" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "location" text NOT NULL, "context" text NOT NULL, "comment" text NOT NULL, "flags" text NOT NULL, "source" text NOT NULL, "previous_source" text NOT NULL, "target" text NOT NULL, "position" integer NOT NULL, "has_suggestion" bool NOT NULL, "has_comment" bool NOT NULL, "has_failing_check" bool NOT NULL, "num_words" integer NOT NULL, "translation_id" integer NOT NULL REFERENCES "trans_translation" ("id"), "content_hash" bigint NOT NULL, "id_hash" bigint NOT NULL, "pending" bool NOT NULL, "state" integer NOT NULL, "priority" integer NOT NULL);
