CREATE TABLE IF NOT EXISTS "lang_plural" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "source" smallint NOT NULL, "number" smallint NOT NULL, "equation" varchar(400) NOT NULL, "language_id" integer NOT NULL REFERENCES "lang_language" ("id"), "type" integer NOT NULL);
CREATE TABLE IF NOT EXISTS "trans_componentlist_components" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "componentlist_id" integer NOT NULL REFERENCES "trans_componentlist" ("id"), "component_id" integer NOT NULL REFERENCES "trans_component" ("id"));
CREATE TABLE IF NOT EXISTS "trans_componentlist" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "slug" varchar(100) NOT NULL UNIQUE, "show_dashboard" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "weblate_auth_group_languages" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "weblate_auth_group" ("id"), "language_id" integer NOT NULL REFERENCES "lang_language" ("id"));
CREATE TABLE IF NOT EXISTS "weblate_auth_group_projects" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "weblate_auth_group" ("id"), "project_id" integer NOT NULL REFERENCES "trans_project" ("id"));
CREATE TABLE IF NOT EXISTS "weblate_auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "codename" varchar(100) NOT NULL UNIQUE, "name" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "weblate_auth_role" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "weblate_auth_role_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "role_id" integer NOT NULL REFERENCES "weblate_auth_role" ("id"), "permission_id" integer NOT NULL REFERENCES "weblate_auth_permission" ("id"));
CREATE TABLE IF NOT EXISTS "weblate_auth_group_roles" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "weblate_auth_group" ("id"), "role_id" integer NOT NULL REFERENCES "weblate_auth_role" ("id"));
CREATE TABLE IF NOT EXISTS "weblate_auth_autogroup" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "match" varchar(200) NOT NULL, "group_id" integer NOT NULL REFERENCES "weblate_auth_group" ("id"));
CREATE TABLE IF NOT EXISTS "weblate_auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE, "language_selection" integer NOT NULL, "internal" bool NOT NULL, "componentlist_id" integer NULL REFERENCES "trans_componentlist" ("id"), "project_selection" integer NOT NULL);
CREATE TABLE IF NOT EXISTS "trans_source" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "timestamp" datetime NOT NULL, "priority" integer NOT NULL, "component_id" integer NOT NULL REFERENCES "trans_component" ("id"), "check_flags" text NOT NULL, "id_hash" bigint NOT NULL, "context" text NOT NULL);
CREATE TABLE IF NOT EXISTS "accounts_auditlog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "activity" varchar(20) NOT NULL, "params" text NOT NULL, "address" char(39) NULL, "timestamp" datetime NOT NULL, "user_agent" varchar(200) NOT NULL, "user_id" integer NOT NULL REFERENCES "weblate_auth_user" ("id"));
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action_time" datetime NOT NULL, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL, "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id"), "user_id" integer NOT NULL REFERENCES "weblate_auth_user" ("id"));
CREATE TABLE IF NOT EXISTS "authtoken_token" ("key" varchar(40) NOT NULL PRIMARY KEY, "created" datetime NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "weblate_auth_user" ("id"));
CREATE TABLE IF NOT EXISTS "legal_agreement" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "tos" date NOT NULL, "timestamp" datetime NOT NULL, "address" char(39) NULL, "user_agent" varchar(200) NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "weblate_auth_user" ("id"));
CREATE TABLE IF NOT EXISTS "social_auth_usersocialauth" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(32) NOT NULL, "uid" varchar(255) NOT NULL, "extra_data" text NOT NULL, "user_id" integer NOT NULL REFERENCES "weblate_auth_user" ("id"));
CREATE TABLE IF NOT EXISTS "trans_vote" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "positive" bool NOT NULL, "suggestion_id" integer NOT NULL REFERENCES "trans_suggestion" ("id"), "user_id" integer NOT NULL REFERENCES "weblate_auth_user" ("id"));
CREATE TABLE IF NOT EXISTS "trans_contributoragreement" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "timestamp" datetime NOT NULL, "component_id" integer NOT NULL REFERENCES "trans_component" ("id"), "user_id" integer NOT NULL REFERENCES "weblate_auth_user" ("id"));
CREATE TABLE IF NOT EXISTS "trans_comment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "comment" text NOT NULL, "timestamp" datetime NOT NULL, "language_id" integer NULL REFERENCES "lang_language" ("id"), "project_id" integer NOT NULL REFERENCES "trans_project" ("id"), "content_hash" bigint NOT NULL, "user_id" integer NULL REFERENCES "weblate_auth_user" ("id"));
CREATE TABLE IF NOT EXISTS "weblate_auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "weblate_auth_user" ("id"), "group_id" integer NOT NULL REFERENCES "weblate_auth_group" ("id"));
CREATE TABLE IF NOT EXISTS "screenshots_screenshot" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "image" varchar(100) NOT NULL, "component_id" integer NOT NULL REFERENCES "trans_component" ("id"), "timestamp" datetime NOT NULL, "user_id" integer NULL REFERENCES "weblate_auth_user" ("id"));
CREATE TABLE IF NOT EXISTS "weblate_auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "username" varchar(150) NOT NULL UNIQUE, "full_name" varchar(150) NOT NULL, "is_superuser" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "email" varchar(190) NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "trans_translation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "revision" varchar(100) NOT NULL, "filename" varchar(200) NOT NULL, "language_code" varchar(20) NOT NULL, "language_id" integer NOT NULL REFERENCES "lang_language" ("id"), "component_id" integer NOT NULL REFERENCES "trans_component" ("id"), "plural_id" integer NOT NULL REFERENCES "lang_plural" ("id"));
CREATE TABLE IF NOT EXISTS "billing_billing_projects" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "billing_id" integer NOT NULL REFERENCES "billing_billing" ("id"), "project_id" integer NOT NULL REFERENCES "trans_project" ("id"));
CREATE TABLE IF NOT EXISTS "billing_billing_owners" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "billing_id" integer NOT NULL REFERENCES "billing_billing" ("id"), "user_id" integer NOT NULL REFERENCES "weblate_auth_user" ("id"));
CREATE TABLE IF NOT EXISTS "trans_suggestion" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "target" text NOT NULL, "language_id" integer NOT NULL REFERENCES "lang_language" ("id"), "project_id" integer NOT NULL REFERENCES "trans_project" ("id"), "user_id" integer NULL REFERENCES "weblate_auth_user" ("id"), "content_hash" bigint NOT NULL, "timestamp" datetime NOT NULL, "userdetails" text NOT NULL);
CREATE TABLE IF NOT EXISTS "billing_plan" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "price" integer NOT NULL, "limit_strings" integer NOT NULL, "limit_languages" integer NOT NULL, "limit_repositories" integer NOT NULL, "limit_projects" integer NOT NULL, "yearly_price" integer NOT NULL, "display_limit_languages" integer NOT NULL, "display_limit_projects" integer NOT NULL, "display_limit_repositories" integer NOT NULL, "display_limit_strings" integer NOT NULL, "change_access_control" bool NOT NULL, "public" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "billing_invoice" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "start" date NOT NULL, "end" date NOT NULL, "payment" text NOT NULL, "currency" integer NOT NULL, "ref" varchar(50) NOT NULL, "note" text NOT NULL, "billing_id" integer NOT NULL REFERENCES "billing_billing" ("id"), "amount" real NOT NULL);
CREATE TABLE IF NOT EXISTS "wladmin_configurationerror" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE, "message" text NOT NULL, "timestamp" datetime NOT NULL, "ignored" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "addons_event" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "addon_id" integer NOT NULL REFERENCES "addons_addon" ("id"), "event" integer NOT NULL);
CREATE TABLE IF NOT EXISTS "trans_alert" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL, "details" text NOT NULL, "component_id" integer NOT NULL REFERENCES "trans_component" ("id"), "timestamp" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "trans_whiteboardmessage" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "message" text NOT NULL, "language_id" integer NULL REFERENCES "lang_language" ("id"), "project_id" integer NULL REFERENCES "trans_project" ("id"), "component_id" integer NULL REFERENCES "trans_component" ("id"), "message_html" bool NOT NULL, "expiry" date NULL, "category" varchar(25) NOT NULL);
CREATE TABLE IF NOT EXISTS "addons_addon" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "configuration" text NOT NULL, "state" text NOT NULL, "component_id" integer NOT NULL REFERENCES "trans_component" ("id"), "project_scope" bool NOT NULL, "repo_scope" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "billing_billing" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "plan_id" integer NOT NULL REFERENCES "billing_plan" ("id"), "state" integer NOT NULL, "in_limits" bool NOT NULL, "paid" bool NOT NULL, "expiry" datetime NULL, "payment" text NOT NULL, "grace_period" integer NOT NULL, "removal" datetime NULL);
CREATE TABLE IF NOT EXISTS "trans_project" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(60) NOT NULL UNIQUE, "slug" varchar(60) NOT NULL UNIQUE, "web" varchar(200) NOT NULL, "mail" varchar(254) NOT NULL, "instructions" varchar(200) NOT NULL, "enable_hooks" bool NOT NULL, "source_language_id" integer NOT NULL REFERENCES "lang_language" ("id"), "access_control" integer NOT NULL, "enable_review" bool NOT NULL, "use_shared_tm" bool NOT NULL, "set_language_team" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "trans_change" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "timestamp" datetime NOT NULL, "target" text NOT NULL, "author_id" integer NULL REFERENCES "weblate_auth_user" ("id"), "dictionary_id" integer NULL REFERENCES "trans_dictionary" ("id"), "translation_id" integer NULL REFERENCES "trans_translation" ("id"), "unit_id" integer NULL REFERENCES "trans_unit" ("id"), "user_id" integer NULL REFERENCES "weblate_auth_user" ("id"), "component_id" integer NULL REFERENCES "trans_component" ("id"), "old" text NOT NULL, "details" text NOT NULL, "project_id" integer NULL REFERENCES "trans_project" ("id"), "comment_id" integer NULL REFERENCES "trans_comment" ("id"), "suggestion_id" integer NULL REFERENCES "trans_suggestion" ("id"), "alert_id" integer NULL REFERENCES "trans_alert" ("id"), "whiteboard_id" integer NULL REFERENCES "trans_whiteboardmessage" ("id"), "action" integer NOT NULL);
