CREATE TABLE IF NOT EXISTS "accounts_subscription" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "notification" varchar(100) NOT NULL, "scope" integer NOT NULL, "frequency" integer NOT NULL, "component_id" integer NULL REFERENCES "trans_component" ("id"), "project_id" integer NULL REFERENCES "trans_project" ("id"), "user_id" integer NOT NULL REFERENCES "weblate_auth_user" ("id"));
CREATE TABLE IF NOT EXISTS "accounts_profile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language" varchar(10) NOT NULL, "suggested" integer NOT NULL, "translated" integer NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "weblate_auth_user" ("id"), "hide_completed" bool NOT NULL, "secondary_in_zen" bool NOT NULL, "hide_source_secondary" bool NOT NULL, "dashboard_component_list_id" integer NULL REFERENCES "trans_componentlist" ("id"), "dashboard_view" integer NOT NULL, "special_chars" varchar(30) NOT NULL, "uploaded" integer NOT NULL, "translate_mode" integer NOT NULL, "editor_link" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "trans_component" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "slug" varchar(100) NOT NULL, "repo" varchar(200) NOT NULL, "push" varchar(200) NOT NULL, "git_export" varchar(200) NOT NULL, "report_source_bugs" varchar(254) NOT NULL, "branch" varchar(200) NOT NULL, "filemask" varchar(200) NOT NULL, "template" varchar(200) NOT NULL, "new_base" varchar(200) NOT NULL, "file_format" varchar(50) NOT NULL, "locked" bool NOT NULL, "allow_translation_propagation" bool NOT NULL, "save_history" bool NOT NULL, "enable_suggestions" bool NOT NULL, "suggestion_voting" bool NOT NULL, "suggestion_autoaccept" smallint unsigned NOT NULL, "check_flags" text NOT NULL, "project_id" integer NOT NULL REFERENCES "trans_project" ("id"), "commit_message" text NOT NULL, "committer_email" varchar(254) NOT NULL, "committer_name" varchar(200) NOT NULL, "license" varchar(150) NOT NULL, "license_url" varchar(200) NOT NULL, "merge_style" varchar(10) NOT NULL, "new_lang" varchar(10) NOT NULL, "vcs" varchar(20) NOT NULL, "edit_template" bool NOT NULL, "agreement" text NOT NULL, "language_regex" varchar(500) NOT NULL, "add_message" text NOT NULL, "delete_message" text NOT NULL, "priority" integer NOT NULL, "commit_pending_age" integer NOT NULL, "push_on_commit" bool NOT NULL, "merge_message" text NOT NULL, "addon_message" text NOT NULL, "language_code_style" varchar(10) NOT NULL, "repoweb" varchar(200) NOT NULL, "linked_component_id" integer NULL REFERENCES "trans_component" ("id"));
CREATE TABLE IF NOT EXISTS "accounts_profile_watched" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "profile_id" integer NOT NULL REFERENCES "accounts_profile" ("id"), "project_id" integer NOT NULL REFERENCES "trans_project" ("id"));
